// Generate Daily Dashboard Report
const financial = $('Get Financial Data (Daily)').all().map(f => f.json);
const leads = $('Get Leads Data (Daily)').all().map(l => l.json);
const now = new Date();
const today = now.toISOString().slice(0, 10);
const thisMonth = now.toISOString().slice(0, 7);

// --- FINANCIAL METRICS ---
const monthlyIncome = financial
  .filter(f => f.date?.startsWith(thisMonth) && f.type === 'income')
  .reduce((sum, f) => sum + parseFloat(f.amount || 0), 0);

const todayIncome = financial
  .filter(f => f.date === today && f.type === 'income')
  .reduce((sum, f) => sum + parseFloat(f.amount || 0), 0);

const monthlyExpenses = financial
  .filter(f => f.date?.startsWith(thisMonth) && f.type === 'expense')
  .reduce((sum, f) => sum + parseFloat(f.amount || 0), 0);

const monthlyProfit = monthlyIncome - monthlyExpenses;

const totalEnrollmentsThisMonth = financial
  .filter(f => f.date?.startsWith(thisMonth) && f.category === 'course_enrollment')
  .length;

// --- LEAD METRICS ---
const stageCounts = {};
for (const lead of leads) {
  const stage = lead.stage || 'unknown';
  stageCounts[stage] = (stageCounts[stage] || 0) + 1;
}

const totalLeads = leads.length;
const newLeadsToday = leads.filter(l => l.created_at?.startsWith(today)).length;
const enrolledCount = stageCounts['enrolled'] || 0;
const lostCount = stageCounts['lost'] || 0;
const conversionRate = totalLeads > 0 ? ((enrolledCount / totalLeads) * 100).toFixed(1) : 0;

// --- PIPELINE HEALTH ---
const pipelineStages = ['new_lead', 'contacted', 'qualified', 'proposal_sent', 'negotiation'];
const pipelineData = pipelineStages.map(s => `${s}: ${stageCounts[s] || 0}`).join(' | ');

return [{
  json: {
    report_date: today,
    report_month: thisMonth,
    // Financial
    today_income: todayIncome,
    monthly_income: monthlyIncome,
    monthly_expenses: monthlyExpenses,
    monthly_profit: monthlyProfit,
    monthly_enrollments: totalEnrollmentsThisMonth,
    // Leads
    total_leads: totalLeads,
    new_leads_today: newLeadsToday,
    enrolled_total: enrolledCount,
    lost_total: lostCount,
    conversion_rate: conversionRate + '%',
    // Pipeline
    pipeline: pipelineData,
    stage_counts: stageCounts
  }
}];

// Generate Weekly Performance Report
const financial = $('Get Financial Data (Weekly)').all().map(f => f.json);
const leads = $('Get Leads Data (Weekly)').all().map(l => l.json);
const now = new Date();
const weekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);
const weekAgoStr = weekAgo.toISOString().slice(0, 10);

// Weekly financial
const weeklyIncome = financial
  .filter(f => f.date >= weekAgoStr && f.type === 'income')
  .reduce((sum, f) => sum + parseFloat(f.amount || 0), 0);

const weeklyEnrollments = financial
  .filter(f => f.date >= weekAgoStr && f.category === 'course_enrollment')
  .length;

// Weekly leads
const newLeadsWeek = leads.filter(l => l.created_at >= weekAgoStr + 'T00:00:00').length;
const convertedWeek = leads.filter(l => 
  l.stage === 'enrolled' && l.updated_at >= weekAgoStr + 'T00:00:00'
).length;

// Source performance
const sourcePerf = {};
for (const lead of leads.filter(l => l.created_at >= weekAgoStr + 'T00:00:00')) {
  const src = lead.source || 'unknown';
  if (!sourcePerf[src]) sourcePerf[src] = { total: 0, enrolled: 0 };
  sourcePerf[src].total++;
  if (lead.stage === 'enrolled') sourcePerf[src].enrolled++;
}

const sourceTable = Object.entries(sourcePerf)
  .map(([src, data]) => `<tr><td>${src}</td><td>${data.total}</td><td>${data.enrolled}</td><td>${data.total > 0 ? ((data.enrolled/data.total)*100).toFixed(0) : 0}%</td></tr>`)
  .join('');

// Average ticket
const avgTicket = weeklyEnrollments > 0 ? (weeklyIncome / weeklyEnrollments).toFixed(2) : 0;

return [{
  json: {
    week_start: weekAgoStr,
    week_end: now.toISOString().slice(0, 10),
    weekly_income: weeklyIncome,
    weekly_enrollments: weeklyEnrollments,
    new_leads_week: newLeadsWeek,
    converted_week: convertedWeek,
    avg_ticket: avgTicket,
    source_table_html: sourceTable,
    weekly_conversion: newLeadsWeek > 0 ? ((convertedWeek / newLeadsWeek) * 100).toFixed(1) + '%' : '0%'
  }
}];
